"""Generate the two documented, stage-parameterized SQL notebooks deterministically."""

import argparse
import sys

from common import ROOT

sys.path.insert(0, str(ROOT / "databricks" / "src"))
from data_model import MARKER, TABLES


def notebook(layer: str, source: str) -> str:
    names = ", ".join(f"'{name}'" for name in TABLES)
    lines = [
        "-- Databricks notebook source",
        "-- Generated by tools/generate_medallion_sql.py from the shared data dictionary.",
        "SELECT assert_true(:catalog IN ('demo_dev', 'demo_test', 'demo_prod'), 'Invalid stage catalog');",
        "",
        "SELECT assert_true(COUNT(*) = 0, 'Refusing to overwrite unowned demo tables')",
        "FROM IDENTIFIER(:catalog || '.information_schema.tables')",
        f"WHERE table_schema = '{layer}' AND table_name IN ({names})",
        f"AND (comment IS NULL OR NOT startswith(comment, '{MARKER}'));",
    ]
    for name, definition in TABLES.items():
        lines.extend(["", "-- COMMAND ----------", ""])
        comment = (MARKER + ": " + definition["description"]).replace("'", "''")
        columns = ", ".join(f"CAST(`{column}` AS {kind}) AS `{column}`"
                            for column, kind, _ in definition["columns"])
        lines.extend([
            f"CREATE OR REPLACE TABLE IDENTIFIER(:catalog || '.{layer}.{name}')",
            f"USING DELTA COMMENT '{comment}'",
            f"AS SELECT DISTINCT {columns}",
            f"FROM IDENTIFIER(:catalog || '.{source}.{name}');",
        ])
        if layer == "gold":
            for column, _, description in definition["columns"]:
                escaped = description.replace("\\", "\\\\").replace("'", "\\'")
                lines.append(
                    f"ALTER TABLE IDENTIFIER(:catalog || '.gold.{name}') "
                    f"ALTER COLUMN `{column}` COMMENT '{escaped}';"
                )
    return "\n".join(lines) + "\n"


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--dry-run", action="store_true")
    args = parser.parse_args()
    for filename, layer, source in (
        ("bronze_to_silver.sql", "silver", "bronze"),
        ("silver_to_gold.sql", "gold", "silver"),
    ):
        path = ROOT / "databricks" / "src" / filename
        content = notebook(layer, source)
        if path.exists() and not path.read_text(encoding="utf-8").startswith(
            "-- Databricks notebook source\n"
            "-- Generated by tools/generate_medallion_sql.py from the shared data dictionary."
        ):
            raise RuntimeError(f"Refusing to overwrite SQL not created by this generator: {path}")
        print(f"{'DRY-RUN: ' if args.dry_run else ''}Generate {path}")
        if not args.dry_run:
            path.write_text(content, encoding="utf-8")


if __name__ == "__main__":
    main()
